@page "/chat"
@layout ChatLayout
@rendermode InteractiveServer
@using sv_532a8ef7593744d2b59066bb8d5aa65d.Services
@inject IChatService ChatService
@inject IJSRuntime JS

<div class="chat-container">
    @* ── Left sidebar: channel list ── *@
    <aside class="channel-sidebar">
        <div class="sidebar-header">
            <h4>Channels</h4>
        </div>
        <ul class="channel-list">
            @if (channels is not null)
            {
                @foreach (var ch in channels)
                {
                    <li class="channel-item @(ch.Id == activeChannelId ? "active" : "")"
                        @onclick="() => SelectChannelAsync(ch)">
                        <div class="channel-name"># @ch.Name</div>
                        <div class="channel-desc">@TruncateDescription(ch.Description)</div>
                        @if (ch.UnreadCount > 0)
                        {
                            <span class="unread-badge">@ch.UnreadCount</span>
                        }
                    </li>
                }
            }
        </ul>
    </aside>

    @* ── Main message area ── *@
    <section class="message-area @(threadOpen ? "thread-visible" : "")">
        @if (activeChannel is not null)
        {
            <div class="message-header">
                <h5># @activeChannel.Name</h5>
                <span class="channel-description">@activeChannel.Description</span>
            </div>

            <div class="message-list" @ref="messageListRef" @onscroll="OnMessageListScroll">
                @if (loadingMore)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @if (messages is not null)
                {
                    @foreach (var msg in messages)
                    {
                        <div class="message-card" @onmouseenter="() => hoveredMessageId = msg.Id"
                             @onmouseleave="() => hoveredMessageId = null">
                            <div class="message-meta">
                                <span class="author">@msg.Author</span>
                                <span class="timestamp">@FormatRelativeTime(msg.SentAt)</span>
                            </div>
                            <div class="message-content">@msg.Content</div>

                            @if (msg.Reactions.Count > 0)
                            {
                                <div class="reaction-row">
                                    @foreach (var r in msg.Reactions)
                                    {
                                        <button class="reaction-badge" @onclick="() => ReactAsync(msg.Id, r.Emoji)">
                                            @r.Emoji @r.Users.Count
                                        </button>
                                    }
                                </div>
                            }

                            @if (threadSummaries.TryGetValue(msg.Id, out var summary))
                            {
                                <button class="thread-link" @onclick="() => OpenThreadAsync(msg)">
                                    @summary.ReplyCount @(summary.ReplyCount == 1 ? "reply" : "replies")
                                </button>
                            }

                            @if (hoveredMessageId == msg.Id)
                            {
                                <div class="message-actions">
                                    <button class="action-btn" @onclick="() => OpenThreadAsync(msg)" title="Reply in thread">
                                        💬 Reply
                                    </button>
                                    <div class="emoji-picker-wrapper">
                                        <button class="action-btn" @onclick="() => ToggleEmojiPicker(msg.Id)" title="Add reaction">
                                            😊 React
                                        </button>
                                        @if (emojiPickerMessageId == msg.Id)
                                        {
                                            <div class="emoji-picker">
                                                @foreach (var emoji in commonEmojis)
                                                {
                                                    <button class="emoji-option" @onclick="() => ReactAsync(msg.Id, emoji)">@emoji</button>
                                                }
                                            </div>
                                        }
                                    </div>
                                </div>
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea @bind="newMessageText" @bind:event="oninput"
                          @onkeydown="OnMessageKeyDown"
                          placeholder="Type a message…" rows="2"></textarea>
                <button class="send-btn" @onclick="SendMessageAsync" disabled="@string.IsNullOrWhiteSpace(newMessageText)">
                    Send
                </button>
            </div>
        }
        else
        {
            <div class="empty-state">Select a channel to start chatting</div>
        }
    </section>

    @* ── Right panel: thread view ── *@
    @if (threadOpen && threadRootMessage is not null)
    {
        <aside class="thread-panel">
            <div class="thread-header">
                <h5>Thread</h5>
                <button class="close-btn" @onclick="CloseThread">✕</button>
            </div>
            <div class="thread-root-quote">
                <span class="author">@threadRootMessage.Author</span>
                <p>@threadRootMessage.Content</p>
            </div>
            <div class="thread-replies">
                @if (threadMessages is not null)
                {
                    @foreach (var reply in threadMessages)
                    {
                        <div class="message-card">
                            <div class="message-meta">
                                <span class="author">@reply.Author</span>
                                <span class="timestamp">@FormatRelativeTime(reply.SentAt)</span>
                            </div>
                            <div class="message-content">@reply.Content</div>
                            @if (reply.Reactions.Count > 0)
                            {
                                <div class="reaction-row">
                                    @foreach (var r in reply.Reactions)
                                    {
                                        <button class="reaction-badge" @onclick="() => ReactAsync(reply.Id, r.Emoji)">
                                            @r.Emoji @r.Users.Count
                                        </button>
                                    }
                                </div>
                            }
                        </div>
                    }
                }
            </div>
            <div class="message-input-area">
                <textarea @bind="threadReplyText" @bind:event="oninput"
                          @onkeydown="OnThreadKeyDown"
                          placeholder="Reply in thread…" rows="2"></textarea>
                <button class="send-btn" @onclick="SendThreadReplyAsync" disabled="@string.IsNullOrWhiteSpace(threadReplyText)">
                    Reply
                </button>
            </div>
        </aside>
    }
</div>

@code {
    private const int PageSize = 30;
    private static readonly string[] commonEmojis = ["👍", "❤️", "😂", "🎉", "🤔", "👀"];

    // Channel state
    private List<Channel>? channels;
    private int activeChannelId;
    private Channel? activeChannel;

    // Message state
    private List<Message>? messages;
    private Dictionary<int, ThreadSummary> threadSummaries = new();
    private int skip;
    private bool hasMore = true;
    private bool loadingMore;
    private string newMessageText = string.Empty;

    // Hover / emoji state
    private int? hoveredMessageId;
    private int? emojiPickerMessageId;

    // Thread state
    private bool threadOpen;
    private Message? threadRootMessage;
    private List<Message>? threadMessages;
    private string threadReplyText = string.Empty;

    private ElementReference messageListRef;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task SelectChannelAsync(Channel channel)
    {
        if (channel.Id == activeChannelId) return;

        activeChannelId = channel.Id;
        activeChannel = channel;
        skip = 0;
        hasMore = true;
        messages = null;
        threadSummaries.Clear();
        CloseThread();

        var loaded = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        messages = loaded;
        skip = loaded.Count;
        hasMore = loaded.Count == PageSize;

        BuildThreadSummaries(loaded);
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Refresh channels to clear unread badge
        channels = await ChatService.GetChannelsAsync();
        StateHasChanged();
        await ScrollToBottom();
    }

    private async Task LoadOlderMessagesAsync()
    {
        if (!hasMore || loadingMore || messages is null) return;

        loadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(activeChannelId, skip, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            skip += older.Count;
            BuildThreadSummaries(older);
        }
        hasMore = older.Count == PageSize;
        loadingMore = false;
    }

    private void BuildThreadSummaries(List<Message> batch)
    {
        // Identify messages that have replies (ReplyToId points to a root message)
        var replyGroups = batch
            .Where(m => m.ReplyToId.HasValue)
            .GroupBy(m => m.ReplyToId!.Value);

        foreach (var g in replyGroups)
        {
            if (threadSummaries.ContainsKey(g.Key))
            {
                var existing = threadSummaries[g.Key];
                threadSummaries[g.Key] = existing with
                {
                    ReplyCount = existing.ReplyCount + g.Count(),
                    LastReplyAt = g.Max(m => m.SentAt)
                };
            }
            else
            {
                threadSummaries[g.Key] = new ThreadSummary(
                    g.Key,
                    g.Count(),
                    g.Max(m => m.SentAt)
                );
            }
        }

        // Also mark messages that are thread roots if GetThreadAsync has previously shown replies
        foreach (var m in batch.Where(m => m.ReplyToId is null && !threadSummaries.ContainsKey(m.Id)))
        {
            // Check if any other message in the full list references this one
            if (messages?.Any(r => r.ReplyToId == m.Id) == true)
            {
                var replies = messages.Where(r => r.ReplyToId == m.Id).ToList();
                threadSummaries[m.Id] = new ThreadSummary(m.Id, replies.Count, replies.Max(r => r.SentAt));
            }
        }
    }

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(newMessageText)) return;

        var sent = await ChatService.SendMessageAsync(activeChannelId, newMessageText, null);
        messages ??= new();
        messages.Add(sent);
        skip++;
        newMessageText = string.Empty;
        StateHasChanged();
        await ScrollToBottom();
    }

    private async Task OnMessageKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMessageAsync();
        }
    }

    private async Task OnMessageListScroll()
    {
        // Use JS interop to check scroll position
        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop < 50)
        {
            await LoadOlderMessagesAsync();
        }
    }

    // ── Thread ──

    private async Task OpenThreadAsync(Message rootMsg)
    {
        threadRootMessage = rootMsg;
        threadMessages = await ChatService.GetThreadAsync(rootMsg.Id);
        threadReplyText = string.Empty;
        threadOpen = true;
        emojiPickerMessageId = null;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadMessages = null;
        threadReplyText = string.Empty;
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(threadReplyText) || threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(activeChannelId, threadReplyText, threadRootMessage.Id);
        threadMessages ??= new();
        threadMessages.Add(reply);

        // Update thread summary in main view
        if (threadSummaries.TryGetValue(threadRootMessage.Id, out var existing))
        {
            threadSummaries[threadRootMessage.Id] = existing with
            {
                ReplyCount = existing.ReplyCount + 1,
                LastReplyAt = reply.SentAt
            };
        }
        else
        {
            threadSummaries[threadRootMessage.Id] = new ThreadSummary(threadRootMessage.Id, 1, reply.SentAt);
        }

        threadReplyText = string.Empty;
    }

    private async Task OnThreadKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendThreadReplyAsync();
        }
    }

    // ── Reactions ──

    private async Task ReactAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        emojiPickerMessageId = null;

        // Refresh messages to pick up the updated reaction
        if (messages is not null)
        {
            var refreshed = await ChatService.GetMessagesAsync(activeChannelId, 0, messages.Count);
            messages = refreshed;
        }

        if (threadOpen && threadRootMessage is not null)
        {
            threadMessages = await ChatService.GetThreadAsync(threadRootMessage.Id);
        }
