+        if (older.Count > 0)
+        {
+            messages.InsertRange(0, older);
+            skip += older.Count;
+            BuildThreadSummaries(older);
+        }
+        hasMore = older.Count == PageSize;
+        loadingMore = false;
+    }
+
+    private void BuildThreadSummaries(List<Message> batch)
+    {
+        // Identify messages that have replies (ReplyToId points to a root message)
+        var replyGroups = batch
+            .Where(m => m.ReplyToId.HasValue)
+            .GroupBy(m => m.ReplyToId!.Value);
+
+        foreach (var g in replyGroups)
+        {
+            if (threadSummaries.ContainsKey(g.Key))
+            {
+                var existing = threadSummaries[g.Key];
+                threadSummaries[g.Key] = existing with
+                {
+                    ReplyCount = existing.ReplyCount + g.Count(),
+                    LastReplyAt = g.Max(m => m.SentAt)
+                };
+            }
+            else
+            {
+                threadSummaries[g.Key] = new ThreadSummary(
+                    g.Key,
+                    g.Count(),
+                    g.Max(m => m.SentAt)
+                );
+            }
+        }
+
+        // Also mark messages that are thread roots if GetThreadAsync has previously shown replies
+        foreach (var m in batch.Where(m => m.ReplyToId is null && !threadSummaries.ContainsKey(m.Id)))
+        {
+            // Check if any other message in the full list references this one
+            if (messages?.Any(r => r.ReplyToId == m.Id) == true)
+            {
+                var replies = messages.Where(r => r.ReplyToId == m.Id).ToList();
+                threadSummaries[m.Id] = new ThreadSummary(m.Id, replies.Count, replies.Max(r => r.SentAt));
+            }
+        }
+    }
+
+    private async Task SendMessageAsync()
+    {
+        if (string.IsNullOrWhiteSpace(newMessageText)) return;
+
+        var sent = await ChatService.SendMessageAsync(activeChannelId, newMessageText, null);
+        messages ??= new();
+        messages.Add(sent);
+        skip++;
+        newMessageText = string.Empty;
+        StateHasChanged();
+        await ScrollToBottom();
+    }
+
+    private async Task OnMessageKeyDown(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter" && !e.ShiftKey)
+        {
+            await SendMessageAsync();
+        }
+    }
+
+    private async Task OnMessageListScroll()
+    {
+        // Use JS interop to check scroll position
+        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
+        if (scrollTop < 50)
+        {
+            await LoadOlderMessagesAsync();
+        }
+    }
+
+    // ── Thread ──
+
+    private async Task OpenThreadAsync(Message rootMsg)
+    {
+        threadRootMessage = rootMsg;
+        threadMessages = await ChatService.GetThreadAsync(rootMsg.Id);
+        threadReplyText = string.Empty;
+        threadOpen = true;
+        emojiPickerMessageId = null;
+    }
+
+    private void CloseThread()
+    {
+        threadOpen = false;
+        threadRootMessage = null;
+        threadMessages = null;
+        threadReplyText = string.Empty;
+    }
+
+    private async Task SendThreadReplyAsync()
+    {
+        if (string.IsNullOrWhiteSpace(threadReplyText) || threadRootMessage is null) return;
+
+        var reply = await ChatService.SendMessageAsync(activeChannelId, threadReplyText, threadRootMessage.Id);
+        threadMessages ??= new();
+        threadMessages.Add(reply);
+
+        // Update thread summary in main view
+        if (threadSummaries.TryGetValue(threadRootMessage.Id, out var existing))
+        {
+            threadSummaries[threadRootMessage.Id] = existing with
+            {
+                ReplyCount = existing.ReplyCount + 1,
+                LastReplyAt = reply.SentAt
+            };
+        }
+        else
+        {
+            threadSummaries[threadRootMessage.Id] = new ThreadSummary(threadRootMessage.Id, 1, reply.SentAt);
+        }
+
+        threadReplyText = string.Empty;
+    }
+
+    private async Task OnThreadKeyDown(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter" && !e.ShiftKey)
+        {
+            await SendThreadReplyAsync();
+        }
+    }
+
+    // ── Reactions ──
+
+    private async Task ReactAsync(int messageId, string emoji)
+    {
+        await ChatService.AddReactionAsync(messageId, emoji);
+        emojiPickerMessageId = null;
+
+        // Refresh messages to pick up the updated reaction
+        if (messages is not null)
+        {
+            var refreshed = await ChatService.GetMessagesAsync(activeChannelId, 0, messages.Count);
+            messages = refreshed;
+        }
+
+        if (threadOpen && threadRootMessage is not null)
+        {
+            threadMessages = await ChatService.GetThreadAsync(threadRootMessage.Id);
+        }
+    }
+
+    private void ToggleEmojiPicker(int messageId)
+    {
+        emojiPickerMessageId = emojiPickerMessageId == messageId ? null : messageId;
+    }
+
+    // ── Helpers ──
+
+    private static string FormatRelativeTime(DateTime sentAt)
+    {
+        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();
+
+        if (diff.TotalSeconds < 60) return "just now";
+        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
+        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
+        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
+        return sentAt.ToString("MMM d, yyyy");
+    }
+
+    private static string TruncateDescription(string desc)
+    {
+        return desc.Length > 40 ? desc[..37] + "…" : desc;
+    }
+
+    private async Task ScrollToBottom()
+    {
+        await Task.Yield();
+        try
+        {
+            await JS.InvokeVoidAsync("eval",
+                "let el = document.querySelector('.message-list'); if(el) el.scrollTop = el.scrollHeight;");
+        }
+        catch { /* component may not be rendered yet */ }
+    }
+}
+

toolArgs.file_text:
/* ── Chat page layout ── */

.chat-container {
    display: flex;
    height: 100vh;
    width: 100vw;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1d1c1d;
    background: #fff;
    overflow: hidden;
    position: fixed;
    top: 0;
    left: 0;
}

/* ── Channel sidebar ── */

.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #3f0e40;
    color: #cfc3cf;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.sidebar-header {
    padding: 16px 16px 8px;
    border-bottom: 1px solid #522653;
}

.sidebar-header h4 {
    margin: 0;
    color: #fff;
    font-size: 1.1rem;
}

.channel-list {
    list-style: none;
    padding: 0;
    margin: 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 4px;
    transition: background 0.15s;
    position: relative;
}

.channel-item:hover {
    background: #4a154b;
}

.channel-item.active {
    background: #1164a3;
    color: #fff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    flex: 1;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.channel-desc {
    width: 100%;
    font-size: 0.75rem;
    opacity: 0.7;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    background: #e01e5a;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 1px 6px;
    border-radius: 10px;
    position: absolute;
    right: 12px;
    top: 10px;
}

/* ── Main message area ── */

.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    border-right: 1px solid #e8e8e8;
}

.message-area.thread-visible {
    flex: 0 0 55%;
}

.message-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e8e8e8;
    background: #fff;
}

.message-header h5 {
    margin: 0 0 2px;
    font-size: 1.05rem;
    font-weight: 700;
}

.channel-description {
    font-size: 0.82rem;
    color: #616061;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 12px 20px;
}

.loading-indicator {
    text-align: center;
    padding: 8px;
    font-size: 0.85rem;
    color: #888;
}

.empty-state {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    font-size: 1.1rem;
    color: #888;
}

/* ── Message card ── */

.message-card {
    padding: 6px 8px;
    border-radius: 6px;
    position: relative;
    transition: background 0.1s;
    margin-bottom: 2px;
}

.message-card:hover {
    background: #f8f8f8;
}

.message-meta {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.author {
    font-weight: 700;
    font-size: 0.92rem;
}

.timestamp {
    font-size: 0.75rem;
    color: #999;
}

.message-content {
    font-size: 0.93rem;
    line-height: 1.45;
    word-break: break-word;
}

/* ── Reactions ── */

.reaction-row {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 4px;
}

.reaction-badge {
    background: #f0f0f0;
    border: 1px solid #ddd;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.15s;
}

.reaction-badge:hover {
    background: #e0e0ff;
    border-color: #aac;
}

/* ── Thread link ── */

.thread-link {
    background: none;
    border: none;
    color: #1264a3;
    font-size: 0.82rem;
    font-weight: 600;
    cursor: pointer;
    padding: 2px 0;
    margin-top: 2px;
}

.thread-link:hover {
    text-decoration: underline;
}

/* ── Message hover actions ── */

.message-actions {
    position: absolute;
    top: -4px;
    right: 8px;
    display: flex;
    gap: 2px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 6px;
    padding: 2px 4px;
    box-shadow: 0 1px 4px rgba(0,0,0,.1);
    z-index: 10;
}

.action-btn {
    background: none;
    border: none;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    white-space: nowrap;
}

.action-btn:hover {
    background: #f0f0f0;
}

.emoji-picker-wrapper {
    position: relative;
}

.emoji-picker {
    position: absolute;
    top: 100%;
    right: 0;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 6px;
    display: flex;
    gap: 2px;
    box-shadow: 0 2px 8px rgba(0,0,0,.15);
    z-index: 20;
}

.emoji-option {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 4px;
    transition: background 0.1s;
}

.emoji-option:hover {
    background: #f0f0f0;
}

/* ── Message input ── */

.message-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #e8e8e8;
    background: #fff;
    align-items: flex-end;
}

.message-input-area textarea {
    flex: 1;
    resize: none;
    border: 1px solid #ccc;
    border-radius: 6px;
    padding: 8px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

.message-input-area textarea:focus {
    border-color: #1264a3;
}

.send-btn {
    background: #007a5a;
    color: #fff;
    border: none;
    border-radius: 6px;
    padding: 8px 20px;
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    white-space: nowrap;
    transition: background 0.15s;
}

.send-btn:hover:not(:disabled) {
    background: #006349;
}

.send-btn:disabled {
    background: #ccc;
    cursor: default;
}

/* ── Thread panel ── */

.thread-panel {
    width: 25%;
    min-width: 260px;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #e8e8e8;
    background: #fff;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #e8e8e8;
}

.thread-header h5 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    color: #666;
}

.close-btn:hover {
    background: #f0f0f0;
}

.thread-root-quote {
    padding: 12px 16px;
    border-bottom: 1px solid #e8e8e8;
    background: #fafafa;
    border-left: 3px solid #1264a3;
    margin: 8px 12px;
    border-radius: 0 4px 4px 0;
}

.thread-root-quote .author {
    font-size: 0.85rem;
}

.thread-root-quote p {
    margin: 4px 0 0;
    font-size: 0.88rem;
    color: #444;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 12px;
}

/* ── Scrollbar styling ── */

.message-list::-webkit-scrollbar,
.thread-replies::-webkit-scrollbar,
.channel-list::-webkit-scrollbar {
    width: 6px;
}

.message-list::-webkit-scrollbar-thumb,
.thread-replies::-webkit-scrollbar-thumb {
    background: #ccc;
    border-radius: 3px;
}

.channel-list::-webkit-scrollbar-thumb {
    background: rgba(255,255,255,.2);
    border-radius: 3px;
}

